router.add_api_route("/cancel_approved_deposit", endpoint=api_control.cancel_approved_deposit, methods=["POST"], response_model=dict)
router.add_api_route("/reservation_room_action", endpoint=api_control.reservation_room_action, methods=["POST"], response_model=dict, dependencies=[Depends(require_roles("reception"))])
router.add_api_route("/update_user_status", endpoint=api_control.update_user_status, methods=["POST"], response_model=dict, dependencies=[Depends(require_roles("reception"))])
router.add_api_route("/reply_approval", endpoint=api_control.reply_approval, methods=["POST"], response_model=dict, dependencies=[Depends(require_roles("reception"))])
router.add_api_route("/worker_reply", endpoint=api_control.worker_reply, methods=["POST"], response_model=dict)
